import { contentPackageSchema, type ContentPackage } from '../../packages/protocol/src/content';

export function regionalFixture(kind: 'snow' | 'volcano' | 'city', center = { x: 0, z: -500 }): ContentPackage {
  const assets = {
    tower: { label: '办公塔楼', materials: { 'surface-7795af': { label: 'Surface', color: '#7795af', roughness: 0.3 }, 'surface-adc4d7': { label: 'Surface', color: '#adc4d7', roughness: 0.4 } }, parts: [{ shape: 'box', size: [6, 32, 6], position: [0, 16, 0], material: 'surface-7795af' }, { shape: 'box', size: [4, 16, 4], position: [0, 28, 0], material: 'surface-adc4d7' }], collider: null, colliders: [{ halfExtents: [3, 18, 3], center: [0, 18, 0] }], effect: 'none' },
    car: { label: '行驶轿车', materials: { 'surface-c44b3e': { label: 'Surface', color: '#c44b3e', roughness: 0.4 }, 'surface-34475a': { label: 'Surface', color: '#34475a', roughness: 0.2 } }, parts: [{ shape: 'box', size: [1.8, 1, 3.6], position: [0, 0.5, 0], material: 'surface-c44b3e' }, { shape: 'box', size: [1.5, 0.5, 2], position: [0, 1.25, 0], material: 'surface-34475a' }], collider: { halfExtents: [0.9, 0.75, 1.8], center: [0, 0.75, 0] }, effect: 'none' },
    spire: { label: '黑曜石尖柱', materials: { 'surface-251d27': { label: 'Surface', color: '#251d27', roughness: 0.25 } }, parts: [{ shape: 'cone', size: [3, 7, 3], position: [0, 3.5, 0], material: 'surface-251d27' }], collider: { halfExtents: [1, 3, 1], center: [0, 3, 0] }, effect: 'none' },
  };
  const region = { center, radius: 120, transition: 28, elevation: 20, preserveCorridors: false, operators: [] as unknown[], surface: { color: '#879281', snowCover: false }, clearing: { vegetation: true, rocks: true, settlements: true }, requirements: {} };
  if (kind === 'snow') { region.operators = [{ kind: 'ridge', height: 52, wavelength: 140, angle: 0.4, offset: { x: 0, z: 0 } }]; region.surface = { color: '#f1f6fb', snowCover: true }; region.requirements = { minRelief: 30, minSnowCoverage: 0.8 }; }
  if (kind === 'volcano') { region.operators = [{ kind: 'volcano', height: 70, radius: 85, craterRadius: 24, craterDepth: 30, offset: { x: 0, z: 0 } }]; region.surface = { color: '#4b3b34', snowCover: false }; region.requirements = { minRelief: 45, minCraterDepth: 15 }; }
  const pack: Record<string, unknown> = { protocol: 2, id: `fixture-${kind}`, version: '1.0.0', title: kind, description: '明确标记的协议测试配方，不代表真实 API 输出', assets: kind === 'city' ? { tower: assets.tower, car: assets.car } : kind === 'volcano' ? { spire: assets.spire } : {}, region };
  if (kind === 'volcano') Object.assign(region, { placements: [{ id: 'obsidian', asset: 'spire', position: { x: 60, z: 0 }, role: 'prop' }] });
  if (kind === 'city') Object.assign(region, { operators: [], roads: [{ id: 'ring', width: 8, closed: true, points: [{ x: -60, z: -60 }, { x: 60, z: -60 }, { x: 60, z: 60 }, { x: -60, z: 60 }] }, { id: 'cross-x', width: 8, points: [{ x: -60, z: 0 }, { x: 60, z: 0 }] }, { id: 'cross-z', width: 8, points: [{ x: 0, z: -60 }, { x: 0, z: 60 }] }], placements: [-25, 25].flatMap((x, i) => [-25, 25].map((z, j) => ({ id: `tower-${i}-${j}`, asset: 'tower', position: { x, z }, role: 'building' }))), vehicles: [{ id: 'car-a', asset: 'car', road: 'ring', speed: 5, phase: 0 }, { id: 'car-b', asset: 'car', road: 'ring', speed: 5, phase: 0.5 }], requirements: { minBuildings: 4, minBuildingHeight: 30, minRoadLength: 200, minVehicles: 2, minMovingVehicles: 2 } });
  return contentPackageSchema.parse(pack);
}
